public static class BuildWorldThree {
 static void Label(Transform parent,string text,Quaternion rotation){var go=new GameObject("WarpLabel_"+text);go.transform.SetParent(parent,false);go.transform.localPosition=new Vector3(0,1.4f,0);go.transform.rotation=rotation;var mesh=go.AddComponent<TextMesh>();mesh.text=text;mesh.font=Resources.GetBuiltinResource<Font>("LegacyRuntime.ttf");mesh.fontSize=64;mesh.characterSize=.07f;mesh.anchor=TextAnchor.MiddleCenter;mesh.color=new Color(.9f,.7f,1f);go.GetComponent<MeshRenderer>().sharedMaterial=mesh.font.material;}
 static Vector2Int P(int x,int y)=>new Vector2Int(x,y);
 static string Kind(char c)=>c=='R'?"Cell_Direction_R":c=='L'?"Cell_Direction_L":c=='U'?"Cell_Direction_F":c=='D'?"Cell_Direction_B":c=='W'?"Cell_Warp":"Cell";
 static void Fixed(TileGroup g){var so=new SerializedObject(g);so.FindProperty("_isStatic").boolValue=true;so.ApplyModifiedPropertiesWithoutUndo();PrefabUtility.RecordPrefabInstancePropertyModifications(g);}
 static GameObject Group(GameObject root,string name,Vector3 at,bool fixedTile){var go=new GameObject(name);go.transform.SetParent(root.transform,false);go.transform.localPosition=at;var g=go.AddComponent<TileGroup>();var so=new SerializedObject(g);so.FindProperty("_isStatic").boolValue=fixedTile;so.ApplyModifiedPropertiesWithoutUndo();return go;}
 static GameObject Cell(GameObject parent,Vector3 at,char type,bool fixedTile){string folder=type=='W'?"Assets/Gimmick/Prefab/TileCell/":"Assets/Tile/Prefab/TileCell/";var go=(GameObject)PrefabUtility.InstantiatePrefab(AssetDatabase.LoadAssetAtPath<GameObject>(folder+Kind(type)+".prefab"),parent.scene);go.transform.SetParent(parent.transform,false);go.transform.localPosition=at;go.name=Kind(type)+"_"+at.x+"_"+at.z;
  if(type!='W')go.GetComponent<MeshRenderer>().sharedMaterial=AssetDatabase.LoadAssetAtPath<Material>("Assets/Tile/Material/"+(fixedTile?"MAT_FixedTile":"MAT_BaseTile")+".mat");
  foreach(var r in go.GetComponentsInChildren<SpriteRenderer>(true).Where(r=>r.sprite!=null&&r.sprite.name=="TEX_Arrow")){r.color=fixedTile?Color.white:Color.black;PrefabUtility.RecordPrefabInstancePropertyModifications(r);}PrefabUtility.RecordPrefabInstancePropertyModifications(go.transform);PrefabUtility.RecordPrefabInstancePropertyModifications(go.GetComponent<MeshRenderer>());return go;
 }
 public static void Capture(Camera cam,string path){var rt=new RenderTexture(1280,720,24);var old=RenderTexture.active;var target=cam.targetTexture;var tex=new Texture2D(1280,720,TextureFormat.RGB24,false);try{cam.targetTexture=rt;cam.Render();RenderTexture.active=rt;tex.ReadPixels(new Rect(0,0,1280,720),0,0);tex.Apply();File.WriteAllBytes(path,tex.EncodeToPNG());}finally{cam.targetTexture=target;RenderTexture.active=old;UnityEngine.Object.DestroyImmediate(tex);UnityEngine.Object.DestroyImmediate(rt);}}
 static void Fit(TileGrid grid,List<Vector2Int> cells){
  var points=cells.SelectMany(p=>new[]{p+P(-2,-2),p+P(-2,2),p+P(2,-2),p+P(2,2)}).Distinct().OrderBy(p=>p.x).ThenBy(p=>p.y).ToList();Func<Vector2Int,Vector2Int,Vector2Int,int> cross=(a,b,c)=>(b.x-a.x)*(c.y-a.y)-(b.y-a.y)*(c.x-a.x);var hull=new List<Vector2Int>();
  foreach(var p in points){while(hull.Count>=2&&cross(hull[hull.Count-2],hull[hull.Count-1],p)<=0)hull.RemoveAt(hull.Count-1);hull.Add(p);}int lower=hull.Count;for(int i=points.Count-2;i>=0;i--){var p=points[i];while(hull.Count>lower&&cross(hull[hull.Count-2],hull[hull.Count-1],p)<=0)hull.RemoveAt(hull.Count-1);hull.Add(p);}hull.RemoveAt(hull.Count-1);
  var allowed=new List<Vector2Int>();for(int x=0;x<grid.GridSize.x;x++)for(int y=0;y<grid.GridSize.y;y++){var p=P(x,y);if(Enumerable.Range(0,hull.Count).All(i=>cross(hull[i],hull[(i+1)%hull.Count],p)>=0))allowed.Add(p);}
  foreach(var p in cells)for(int x=-2;x<=2;x++)for(int y=-2;y<=2;y++)if(!allowed.Contains(p+P(x,y)))throw new Exception("Padding outside grid");var so=new SerializedObject(grid);var list=so.FindProperty("_placementPositions");list.arraySize=allowed.Count;for(int i=0;i<allowed.Count;i++)list.GetArrayElementAtIndex(i).vector2IntValue=allowed[i];so.ApplyModifiedPropertiesWithoutUndo();grid.RefreshPlacementArea();PrefabUtility.RecordPrefabInstancePropertyModifications(grid);
  var cam=Camera.main;float minX=float.MaxValue,maxX=float.MinValue,minY=float.MaxValue,maxY=float.MinValue;foreach(var p in allowed)foreach(float x in new[]{-.5f,.5f})foreach(float z in new[]{-.5f,.5f})foreach(float y in new[]{-.5f,1.6f}){var v=grid.GridToWorld(p)+new Vector3(x,y,z);float sx=Vector3.Dot(v,cam.transform.right),sy=Vector3.Dot(v,cam.transform.up);minX=Math.Min(minX,sx);maxX=Math.Max(maxX,sx);minY=Math.Min(minY,sy);maxY=Math.Max(maxY,sy);}cam.transform.position+=cam.transform.right*((minX+maxX)/2-Vector3.Dot(cam.transform.position,cam.transform.right))+cam.transform.up*((minY+maxY)/2-Vector3.Dot(cam.transform.position,cam.transform.up));cam.orthographicSize=Math.Max((maxY-minY)/2+.65f,((maxX-minX)/2+.65f)/(16f/9f));PrefabUtility.RecordPrefabInstancePropertyModifications(cam);PrefabUtility.RecordPrefabInstancePropertyModifications(cam.transform);
 }
 public static string Run(){
  if(EditorApplication.isPlayingOrWillChangePlaymode)throw new Exception("Playing");for(int i=0;i<SceneManager.sceneCount;i++)if(SceneManager.GetSceneAt(i).isDirty)throw new Exception("Unsaved scene");Directory.CreateDirectory("Logs/WorldThree");var setup=EditorSceneManager.GetSceneManagerSetup();var log=new StringBuilder();
  try{for(int s=1;s<=4;s++){
   string sp=$"Assets/NormalStage/stage3-{s}/stage3-{s}.unity",pp=$"Assets/NormalStage/stage3-{s}/Stage3-{s}_Layout.prefab";var scene=EditorSceneManager.OpenScene(sp,OpenSceneMode.Single);var grid=UnityEngine.Object.FindFirstObjectByType<TileGrid>();var sr=PrefabUtility.GetOutermostPrefabInstanceRoot(grid.GetComponentsInChildren<TileGroup>()[0].gameObject);bool outsideController=grid.GetComponentsInChildren<OnOffController>().Any(c=>!c.transform.IsChildOf(sr.transform));Func<Vector2Int,Vector3> local=p=>sr.transform.InverseTransformPoint(grid.GridToWorld(p));
   var start=s==1?P(8,14):s==2?P(10,12):s==3?P(14,14):P(21,11);var key=s==1?P(19,14):s==2?P(22,18):s==3?P(9,21):P(10,16);var goal=s==1?P(25,16):s==2?P(12,16):s==3?P(8,9):P(17,22);
   var root=PrefabUtility.LoadPrefabContents(pp);
   try{
