    if(root.GetComponentsInChildren<OnOffController>().Length==0&&!outsideController){var controller=(GameObject)PrefabUtility.InstantiatePrefab(AssetDatabase.LoadAssetAtPath<GameObject>("Assets/Gimmick/Prefab/OnOffController.prefab"),root.scene);controller.transform.SetParent(root.transform,false);}
