    Action<string,int,int,int,int> island=(name,x,y,w,h)=>{var group=Group(root,name,local(P(x,y)),true);for(int dx=0;dx<w;dx++)for(int dy=0;dy<h;dy++){var p=P(x+dx,y+dy);if(!occupied.Add(p))throw new Exception("Overlap "+p);Cell(group,local(p)-local(P(x,y)),'.',true);}};
    Action<string,Vector2Int,string> special=(name,p,kind)=>{if(!occupied.Add(p))throw new Exception("Overlap "+p);string asset="Assets/Gimmick/Prefab/TileGroup/"+(kind=="S"?"Group_OnOffSwitch":kind=="O"?"Group_OnOffFloor_On":"Group_OnOffFloor_Off")+".prefab";var go=(GameObject)PrefabUtility.InstantiatePrefab(AssetDatabase.LoadAssetAtPath<GameObject>(asset),root.scene);go.name=name;go.transform.SetParent(root.transform,false);go.transform.localPosition=local(p);Fixed(go.GetComponent<TileGroup>());PrefabUtility.RecordPrefabInstancePropertyModifications(go.transform);PrefabUtility.RecordPrefabInstancePropertyModifications(go);};
