    var specs=new List<(string name,Vector2Int at,Vector2Int[] cells,string types)>();var H2=new[]{P(0,0),P(1,0)};var H3=new[]{P(0,0),P(1,0),P(2,0)};var V2=new[]{P(0,0),P(0,1)};var V3=new[]{P(0,0),P(0,1),P(0,2)};
