     specs.Add(("Arrival_Bridge",P(12,11),H2,".."));specs.Add(("Arrival_Rise",P(21,18),new[]{P(0,0),P(1,0),P(1,1),P(1,2)},".U.R"));specs.Add(("Arrival_SpareTurn",P(16,17),V3,"U.L"));specs.Add(("Arrival_SpareBridge",P(11,18),H3,"..."));
    }else if(s==2){
