     specs.Add(("Loop_Link",P(11,9),V2,".."));specs.Add(("Loop_Corner",P(23,22),V3,"U.L"));specs.Add(("Loop_Descent",P(7,19),new[]{P(0,0),P(0,-1),P(0,-2),P(1,-2)},"D.R."));specs.Add(("Loop_Bridge",P(14,18),H2,".."));specs.Add(("Loop_SpareRise",P(16,10),new[]{P(0,0),P(1,0),P(1,1),P(1,2)},".U.R"));specs.Add(("Loop_SpareBridge",P(15,22),H3,"..."));
    }else if(s==3){
     island("Hub_Center",13,13,3,2);tile("Hub_ReturnLanding",P(11,14),'.');tile("Hub_Link",P(12,14),'.');warp("Hub_KeyGate",P(14,17),P(9,21));tile("Hub_KeyLanding",P(9,21),'.');tile("Hub_KeyCorner",P(9,22),'R');tile("Hub_KeyExit",P(10,22),'.');warp("Hub_KeyReturn",P(11,22),P(11,14));warp("Hub_SwitchGate",P(17,14),P(22,10));tile("Hub_SwitchLanding",P(22,10),'.');special("Hub_RemoteButton",P(23,10),"S");warp("Hub_SwitchReturn",P(23,12),P(18,16));tile("Hub_ReturnFromSwitch",P(18,16),'.');special("Hub_OrangeGate",P(17,16),"O");warp("Hub_GoalGate",P(15,16),P(10,9));island("Hub_GoalLanding",9,9,2,1);special("Hub_BlueShortcut",P(12,15),"B");special("Hub_LocalButton",P(13,12),"S");
     specs.Add(("Hub_LinkPiece",P(11,17),V2,".."));specs.Add(("Hub_UpLeft",P(24,13),V3,"U.L"));specs.Add(("Hub_UpRight",P(18,10),V3,"U.R"));specs.Add(("Hub_DownRight",P(7,16),new[]{P(0,0),P(0,-1),P(0,-2)},"D.R"));specs.Add(("Hub_Bridge",P(15,20),H3,"..."));
    }else{
     island("Relay_Start",21,10,2,2);special("Relay_BlueStartA",P(20,11),"B");special("Relay_BlueStartB",P(19,11),"B");special("Relay_ButtonA",P(18,11),"S");warp("Relay_WarpA",P(17,11),P(9,18));island("Relay_LandingA",8,18,2,1);special("Relay_OrangeKey",P(9,16),"O");tile("Relay_Key",P(10,16),'.');special("Relay_ButtonB",P(11,16),"S");special("Relay_BlueExit",P(12,16),"B");tile("Relay_ExitRest",P(13,16),'.');warp("Relay_WarpB",P(17,16),P(21,20));island("Relay_LandingB",21,20,2,1);special("Relay_ButtonC",P(23,20),"S");special("Relay_OrangeExit",P(24,20),"O");warp("Relay_WarpC",P(21,22),P(16,24));island("Relay_LandingC",15,24,2,1);special("Relay_OrangeGoal",P(16,22),"O");island("Relay_RecoveryIsland",14,18,2,1);warp("Relay_RetryGate",P(16,13),P(21,11));
     specs.Add(("Relay_Descent",P(6,20),new[]{P(0,0),P(0,-1),P(0,-2),P(1,-2)},"D.R."));specs.Add(("Relay_UpLeft",P(24,23),V3,"U.L"));specs.Add(("Relay_Bridge",P(11,20),H3,"..."));specs.Add(("Relay_SpareRise",P(20,8),new[]{P(0,0),P(1,0),P(1,1),P(1,2)},".U.R"));specs.Add(("Relay_SpareLink",P(10,22),V2,".."));
    }
    foreach(var spec in specs){var choices=new List<Vector2Int>();for(int x=4;x<=25;x++)for(int y=5;y<=24;y++){var at=P(x,y);if(spec.cells.All(o=>at.x+o.x>=2&&at.x+o.x<=26&&at.y+o.y>=2&&at.y+o.y<=26&&!occupied.Any(q=>Math.Abs(q.x-at.x-o.x)+Math.Abs(q.y-at.y-o.y)<2)))choices.Add(at);}var pos=choices.OrderBy(p=>(p-spec.at).sqrMagnitude).First();var group=Group(root,spec.name,local(pos),false);for(int i=0;i<spec.cells.Length;i++){Cell(group,local(pos+spec.cells[i])-local(pos),spec.types[i],false);occupied.Add(pos+spec.cells[i]);}}
    var byPoint=root.GetComponentsInChildren<TileCell>().ToDictionary(c=>grid.WorldToGrid(sr.transform.TransformPoint(root.transform.InverseTransformPoint(c.transform.position))));int warpId=0;
    foreach(var w in root.GetComponentsInChildren<Warp>().OrderBy(w=>w.GetComponentInParent<TileGroup>().name)){var p=grid.WorldToGrid(sr.transform.TransformPoint(root.transform.InverseTransformPoint(w.transform.position)));string id=((char)('A'+warpId++)).ToString();Label(w.transform,id,Camera.main.transform.rotation);if(!byPoint.TryGetValue(p+w.WarpAmount,out var destination))throw new Exception("Missing warp destination");Label(destination.transform,id,Camera.main.transform.rotation);}
