    PrefabUtility.SaveAsPrefabAsset(root,pp);
   }finally{PrefabUtility.UnloadPrefabContents(root);}
   scene=EditorSceneManager.OpenScene(sp,OpenSceneMode.Single);grid=UnityEngine.Object.FindFirstObjectByType<TileGrid>();var player=UnityEngine.Object.FindFirstObjectByType<Player>();player.transform.position=grid.GridToWorld(start);var ps=new SerializedObject(player);ps.FindProperty("_startDirection").vector2IntValue=s==3?Vector2Int.up:s==4?Vector2Int.left:Vector2Int.right;ps.FindProperty("_moveSpeed").floatValue=.5f;ps.FindProperty("_startDelay").floatValue=s==1?3:2;ps.ApplyModifiedPropertiesWithoutUndo();PrefabUtility.RecordPrefabInstancePropertyModifications(player);PrefabUtility.RecordPrefabInstancePropertyModifications(player.transform);
   foreach(var item in UnityEngine.Object.FindObjectsByType<GridItem>(FindObjectsSortMode.None)){var so=new SerializedObject(item);so.FindProperty("_gridPosition").vector2IntValue=key;so.ApplyModifiedPropertiesWithoutUndo();item.ApplyGridPosition();PrefabUtility.RecordPrefabInstancePropertyModifications(item);PrefabUtility.RecordPrefabInstancePropertyModifications(item.transform);}
   var controllers=grid.GetComponentsInChildren<OnOffController>();if(controllers.Length!=1)throw new Exception("Expected one controller");var cs=new SerializedObject(controllers[0]);cs.FindProperty("_startOn").boolValue=false;cs.ApplyModifiedPropertiesWithoutUndo();PrefabUtility.RecordPrefabInstancePropertyModifications(controllers[0]);
   var groups=grid.GetComponentsInChildren<TileGroup>();var cells=grid.GetComponentsInChildren<TileCell>();var points=cells.Select(c=>grid.WorldToGrid(c.transform.position)).ToList();if(points.Count!=points.Distinct().Count())throw new Exception("Scene overlap");Fit(grid,points.Concat(new[]{key}).ToList());foreach(var g in groups){g.InitGroup(grid.TileSize);if(!grid.SetTile(g,grid.WorldToGrid(g.transform.position)))throw new Exception("Registration failed "+g.name);}
