   EditorSceneManager.MarkSceneDirty(scene);EditorSceneManager.SaveScene(scene);Capture(Camera.main,$"Logs/WorldThree/stage3-{s}.png");Export(s,grid,player,key,goal);log.AppendLine($"3-{s}: {cells.Length} cells, {groups.Count(g=>!g.IsStatic)} movable groups, {grid.GetComponentsInChildren<Warp>().Length} fixed warps, {grid.GetComponentsInChildren<OnOffSwitch>().Length} fixed switches.");
  }}finally{EditorSceneManager.RestoreSceneManagerSetup(setup);}File.WriteAllText("Logs/WorldThree/build.txt",log.ToString());return log.ToString();
