 static void Export(int s,TileGrid grid,Player player,Vector2Int key,Vector2Int goal){var start=grid.WorldToGrid(player.transform.position);var dir=new SerializedObject(player).FindProperty("_startDirection").vector2IntValue;var data=new JObject{{"start",new JArray(start.x,start.y)},{"direction",new JArray(dir.x,dir.y)},{"key",new JArray(key.x,key.y)},{"goal",new JArray(goal.x,goal.y)}};
  data["groups"]=new JArray(grid.GetComponentsInChildren<TileGroup>().Select(g=>{var at=grid.WorldToGrid(g.transform.position);var floor=g.GetComponent<OnOffFloor>();return new JObject{{"name",g.name},{"fixed",g.IsStatic},{"at",new JArray(at.x,at.y)},{"state",floor==null?-1:floor.SolidWhenOn?1:0},{"cells",new JArray(g.GetComponentsInChildren<TileCell>().Select(c=>{var p=grid.WorldToGrid(c.transform.position)-at;var cd=c.GetComponent<ChangeDirection>();var d=cd==null?Vector2Int.zero:new SerializedObject(cd).FindProperty("_direction").vector2IntValue;var w=c.GetComponent<Warp>();return new JArray(p.x,p.y,d.x,d.y,c.GetComponent<OnOffSwitch>()!=null?1:0,w==null?0:w.WarpAmount.x,w==null?0:w.WarpAmount.y);} ))}};}));
  var prop=new SerializedObject(grid).FindProperty("_placementPositions");data["allowed"]=new JArray(Enumerable.Range(0,prop.arraySize).Select(i=>{var p=prop.GetArrayElementAtIndex(i).vector2IntValue;return new JArray(p.x,p.y);}));File.WriteAllText($"Logs/WorldThree/stage{s}.json",data.ToString());
 }
